240.sql:
SELECT DISTINCT element
FROM atom
WHERE molecule_id = 'TR004';

267.sql:
SELECT DISTINCT bond_type
FROM bond
WHERE molecule_id BETWEEN 'TR000' AND 'TR050' AND bond_type IN ('=', '-', '#');

286.sql:
SELECT CAST(COUNT(*) AS REAL) * 100 / (SELECT COUNT(*) FROM bond WHERE bond_type = '#') AS percent
FROM bond
WHERE bond_type = '#';

387.sql:
SELECT name, colors 
FROM cards 
WHERE setCode = 'OGW';

419.sql:
WITH filtered_cards AS (
    SELECT id
    FROM cards
    WHERE borderColor = 'borderless' AND edhrecRank > 12000
)
SELECT COUNT(*) AS answer FROM filtered_cards;

436.sql:
WITH card_ids AS (
    SELECT id
    FROM cards
    WHERE frameEffects = 'extendedart'
)
SELECT COUNT(id) AS total_cards, GROUP_CONCAT(id) AS card_ids FROM card_ids;

448.sql:
WITH c_cols AS (
    SELECT cd.name, cd.type
    FROM cards cd
    WHERE cd.watermark = 'abzan'
)
SELECT * FROM c_cols;

479.sql:
WITH c_cols AS (
    SELECT id, convertedManaCost, power
    FROM cards
    WHERE name = 'Coldsnap' AND convertedManaCost > 5
)
SELECT COUNT(*) FROM c_cols WHERE power = '*' OR power IS NULL;

549.sql:
WITH tag_info AS (
    SELECT ExcerptPostId
    FROM tags
    WHERE TagName = 'bayesian'
)
SELECT Body FROM posts WHERE Id = (SELECT ExcerptPostId FROM tag_info);

591.sql:
WITH badge_years AS (
    SELECT UserId
    FROM badges
    WHERE Name = 'Supporter' AND STRFTIME('%Y', Date) = '2011'
),
user_counts AS (
    SELECT COUNT(DISTINCT UserId) AS answer
    FROM badge_years
)
SELECT answer FROM user_counts;

617.sql:
SELECT Text 
FROM comments 
WHERE CreationDate = '2010-07-19 19:37:33.0';

631.sql:
WITH user_posts AS (
    SELECT Id
    FROM users
    WHERE DisplayName = 'Daniel Vassallo'
)
SELECT COUNT(*) FROM posts WHERE OwnerUserId IN (SELECT Id FROM user_posts);

729.sql:
WITH marvel_superheroes AS (
    SELECT id, height_cm
    FROM superhero
    WHERE publisher_id IN (SELECT id FROM publisher WHERE publisher_name = 'Marvel Comics')
)
SELECT AVG(height_cm) AS average_height FROM marvel_superheroes;

997.sql:
WITH nationalities AS (
    SELECT nationality, COUNT(*) AS count
    FROM drivers
    GROUP BY nationality
)
SELECT nationality FROM nationalities WHERE count = (SELECT MAX(count) FROM nationalities);

1035.sql:
SELECT team_fifa_api_id 
FROM Team_Attributes 
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

1393.sql:
SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';
